// N×M floorplan infill — the program path CROSSING INTO DESIGN (T-081-01, story S-081, epic E-23).
// DEPENDS ON the hollow shell from T-080-01 (an empty interior) and the structural read from T-078-01.
//
// The hollow cottage is an EMPTY SHELL; this fills the N storeys with floors, dividing walls and interior
// doorways generated by a program the LLM AUTHORS/STEERS from the below/plan view. The interior has NO
// REFERENCE (concept + GLB are exterior shells) — "break into rooms" is INVENTION — so the gate is
// PLAUSIBILITY, not resemblance.
//
// THE PROGRAM-AUTHOR SPLIT (same seam as hollowable-mass.mjs):
//   • the LLM (metered, STRONG tier — the rubric's "authoring a generator") returns a small FloorplanSpec
//     {rows, cols, materials, doorPolicy, frontDoor?} — the floorplan REASONING;
//   • a PURE generator partitions the footprint into an N×M grid and PLACES the bulk (floors at the storey
//     lines, dividing walls on the grid, doorways aligned behind the front door) — "not hand-placed";
//   • a PURE plausibility gate scores rooms-valid / non-overlapping / reachable / floors@lines /
//     storey-count / grid-fits / openings-align, per-constraint, with a NAMED residual (Rule 7).
//
// EXTERIOR-SAFE BY CONSTRUCTION: every placed cell is an ENCLOSED interior column (inside the shell at its
// storey's height), so no front-most ortho surface voxel changes — the fill is invisible from outside and
// `exteriorHeld` (reused from hollow-carve.mjs) proves it. Doorways are made by NOT placing the wall cell
// (`facade-recess-by-exclusion`) — NO air op, NO delete. Placed blocks come ONLY from the artifact's
// palette manifest, so the carved+filled artifact stays AJV-valid.
//
// PURE — no GL, no I/O, no model, no Date/random — runs under the `src/**/*.test.mjs` glob. The GL renders
// + the metered steering call live in the runner (benchmarks/sculpture/floorplan-cottage.mjs).

import { applyDeltas } from "./surface-coherence.mjs";
import { openings, airComponents } from "./structural-read.mjs";
import { parseJsonReply } from "./json-reply.mjs";

/** Schema tag for the floorplan plan + report. */
export const FLOORPLAN_SCHEMA = "floorplan/v1";
/** The op's tier (single point of declaration; mirrored in model-tier OP_ROUTING). Authoring a generator. */
export const TIER = "strong";
/** Floor/wall defaults — both in the cottage manifest; the parser's fallback so a garbled spec still fills. */
export const DEFAULT_MATERIALS = Object.freeze({
  floor: "minecraft:spruce_planks",
  wall: "minecraft:cobblestone",
});

const SIDE_FACES = ["+x", "-x", "+z", "-z"];

// ----------------------------------------------------------------------------------------------------
// Generator geometry (pure, deterministic) — the partition the LLM should NOT compute by hand.
// ----------------------------------------------------------------------------------------------------

/**
 * Derive storeys from the structural read's floor lines. Storey i spans [floorLines[i] .. floorLines[i+1]-1];
 * the top storey runs to the build's top band. Storey COUNT = floorLines.length — the anchor the gate's
 * "storey count matches" checks. PURE.
 * @param {{storeyBands:{bands:object[], floorLines:number[]}}} read a structuralRead result
 * @returns {{index:number, floorY:number, ceilY:number}[]}
 */
export function storeysFromRead(read) {
  const lines = [...(read?.storeyBands?.floorLines ?? [])].sort((a, b) => a - b);
  if (lines.length === 0) return [];
  const bands = read?.storeyBands?.bands ?? [];
  const topY = bands.length ? bands[bands.length - 1].yEnd : lines[lines.length - 1];
  return lines.map((floorY, i) => ({
    index: i,
    floorY,
    ceilY: i + 1 < lines.length ? lines[i + 1] - 1 : Math.max(floorY, topY),
  }));
}

/** Inset a footprint bbox by `inset` columns — the interior envelope the grid partitions (the perimeter
 *  wall is the shell, not ours to place). PURE. */
export function interiorBBox(bbox, inset = 1) {
  if (!bbox) return null;
  return { x0: bbox.minX + inset, x1: bbox.maxX - inset, z0: bbox.minZ + inset, z1: bbox.maxZ - inset };
}

/** Evenly split an inclusive integer range [lo..hi] into `n` bands, returning the n-1 DIVIDER positions
 *  (one-column walls) strictly inside the range. Distinct + ascending; a divider that would collapse a
 *  band to zero width is dropped (the gate then reports the degenerate room). PURE. */
function dividers(lo, hi, n) {
  const width = hi - lo + 1;
  const out = [];
  for (let j = 1; j < n; j++) {
    const p = lo + Math.round((j * width) / n);
    if (p > lo && p < hi && (out.length === 0 || p > out[out.length - 1] + 1)) out.push(p);
  }
  return out;
}

/** The room column-bands between/around the dividers in [lo..hi] (excluding the divider columns). PURE. */
function bandsBetween(lo, hi, divs) {
  const bands = [];
  let start = lo;
  for (const d of divs) {
    if (d - 1 >= start) bands.push([start, d - 1]);
    start = d + 1;
  }
  if (hi >= start) bands.push([start, hi]);
  return bands;
}

/**
 * Partition an interior bbox into an N×M grid: `cols-1` vertical dividers (wall-x lines), `rows-1`
 * horizontal dividers (wall-z lines), and the rows×cols rooms (column boxes BETWEEN the dividers). Pure
 * lattice arithmetic — exactly what the metered call delegates to the program. PURE.
 * @param {{minX,maxX,minZ,maxZ}} footprintBBox
 * @param {{rows:number, cols:number, inset?:number}} opts
 * @returns {{interior:object|null, xWalls:number[], zWalls:number[],
 *   rooms:{id:string, ci:number, ri:number, x0:number, x1:number, z0:number, z1:number}[]}}
 */
export function gridPartition(footprintBBox, { rows, cols, inset = 1 } = {}) {
  const interior = interiorBBox(footprintBBox, inset);
  if (!interior || interior.x0 > interior.x1 || interior.z0 > interior.z1) {
    return { interior, xWalls: [], zWalls: [], rooms: [] };
  }
  const xWalls = dividers(interior.x0, interior.x1, Math.max(1, cols | 0));
  const zWalls = dividers(interior.z0, interior.z1, Math.max(1, rows | 0));
  const xBands = bandsBetween(interior.x0, interior.x1, xWalls);
  const zBands = bandsBetween(interior.z0, interior.z1, zWalls);
  const rooms = [];
  for (let ri = 0; ri < zBands.length; ri++) {
    for (let ci = 0; ci < xBands.length; ci++) {
      rooms.push({
        id: `r${ri}c${ci}`, ci, ri,
        x0: xBands[ci][0], x1: xBands[ci][1], z0: zBands[ri][0], z1: zBands[ri][1],
      });
    }
  }
  return { interior, xWalls, zWalls, rooms };
}

/** Binary (x,z) occupancy mask of the height-`y` slice over the footprint bbox, in `airComponents`'
 *  `{w,h,data}` convention (data[v*w+u]=1 ⇒ occupied). PURE. */
function sliceMaskAtY(occ, y, bbox) {
  const w = bbox.maxX - bbox.minX + 1;
  const h = bbox.maxZ - bbox.minZ + 1;
  const data = new Uint8Array(w * h);
  for (let z = bbox.minZ; z <= bbox.maxZ; z++) {
    for (let x = bbox.minX; x <= bbox.maxX; x++) {
      if (occ.has(x, y, z)) data[(z - bbox.minZ) * w + (x - bbox.minX)] = 1;
    }
  }
  return { w, h, data };
}

/**
 * The room-air columns inside the shell at height `y`: ENCLOSED air components of the (x,z) slice (the same
 * "touches no border ⇒ enclosed" rule `openings`/holes use). Returns world `"x,z"` keys. This gates every
 * placed cell so floors/walls never poke through the gabled roof or the outer wall (the upper storey is
 * narrower than the ground footprint). PURE.
 * @param {import("./occupancy.mjs").Occupancy} occ
 * @param {number} y
 * @returns {Set<string>}
 */
export function interiorColumnsAtY(occ, y) {
  const cols = new Set();
  if (!occ.bounds) return cols;
  const bbox = { minX: occ.bounds.min[0], maxX: occ.bounds.max[0], minZ: occ.bounds.min[2], maxZ: occ.bounds.max[2] };
  const mask = sliceMaskAtY(occ, y, bbox);
  for (const comp of airComponents(mask)) {
    const b = comp.borders;
    if (b.top || b.bottom || b.left || b.right) continue; // reaches outside → not interior
    for (const [u, v] of comp.cellsUV) cols.add(`${bbox.minX + u},${bbox.minZ + v}`);
  }
  return cols;
}

/** Which room (if any) a column falls in — a column ON a divider belongs to no room. PURE. */
export function roomOfColumn(rooms, x, z) {
  for (const r of rooms) if (x >= r.x0 && x <= r.x1 && z >= r.z0 && z <= r.z1) return r;
  return null;
}

// ----------------------------------------------------------------------------------------------------
// The plan + the bulk placements (pure — "the program places").
// ----------------------------------------------------------------------------------------------------

const isWallColumn = (grid, x, z) => grid.xWalls.includes(x) || grid.zWalls.includes(z);

/** The center column of an inclusive range. */
const mid = (lo, hi) => Math.floor((lo + hi) / 2);

/**
 * Doorway cells to EXCLUDE from the dividing walls (the opening is the ABSENCE of wall — no air op). One
 * 1-wide × 2-tall gap per grid-adjacent room pair, centered on their shared edge at the storey floor, so
 * the storey's room graph is connected (reachable). Returns the excluded `"x,y,z"` keys + the door records
 * (room pair) the gate reads. PURE.
 */
function doorways(grid, floorY, existingRooms) {
  const exclude = new Set();
  const doors = [];
  const present = new Set(existingRooms.map((r) => r.id));
  const byCell = new Map(grid.rooms.map((r) => [`${r.ci},${r.ri}`, r]));
  for (const r of grid.rooms) {
    if (!present.has(r.id)) continue;
    // horizontal neighbour (ci+1) — shared vertical wall at x = the divider between the two x-bands
    const east = byCell.get(`${r.ci + 1},${r.ri}`);
    if (east && present.has(east.id)) {
      const wallX = r.x1 + 1; // the divider column between r and east
      const z = mid(Math.max(r.z0, east.z0), Math.min(r.z1, east.z1));
      exclude.add(`${wallX},${floorY + 1},${z}`);
      exclude.add(`${wallX},${floorY + 2},${z}`);
      doors.push({ rooms: [r.id, east.id], cell: [wallX, floorY + 1, z] });
    }
    // vertical neighbour (ri+1) — shared horizontal wall at z = the divider between the two z-bands
    const south = byCell.get(`${r.ci},${r.ri + 1}`);
    if (south && present.has(south.id)) {
      const wallZ = r.z1 + 1;
      const x = mid(Math.max(r.x0, south.x0), Math.min(r.x1, south.x1));
      exclude.add(`${x},${floorY + 1},${wallZ}`);
      exclude.add(`${x},${floorY + 2},${wallZ}`);
      doors.push({ rooms: [r.id, south.id], cell: [x, floorY + 1, wallZ] });
    }
  }
  return { exclude, doors };
}

/**
 * Generate the floorplan: partition the footprint, then PLACE floors at the storey lines, dividing walls
 * on the grid (minus doorways), gated to each storey's enclosed interior. Returns the abstract `plan` (for
 * the gate) and the `placements` ({op:"voxel"} only) to append to the shell. PURE.
 * @param {import("./occupancy.mjs").Occupancy} occ the hollow shell
 * @param {object} read a structuralRead result
 * @param {{rows:number, cols:number, materials?:{floor:string,wall:string}, doorPolicy?:string,
 *   frontDoor?:{face:string,u:number}}} spec the steered FloorplanSpec
 * @returns {{plan:object, placements:{op:"voxel",pos:number[],block:string}[]}}
 */
export function generateFloorplan(occ, read, spec = {}) {
  const materials = { ...DEFAULT_MATERIALS, ...(spec.materials || {}) };
  const fpBBox = read?.footprint?.bbox ?? null;
  const storeys = storeysFromRead(read);
  const grid = gridPartition(fpBBox, { rows: spec.rows ?? 2, cols: spec.cols ?? 2 });
  const placements = [];
  const planStoreys = [];

  for (const st of storeys) {
    // interior columns just above the floor define the storey's rooms (the room-air footprint there)
    const floorCols = interiorColumnsAtY(occ, st.floorY + 1);
    const existingRooms = grid.rooms.filter((r) => {
      for (const key of floorCols) {
        const [x, z] = key.split(",").map(Number);
        if (x >= r.x0 && x <= r.x1 && z >= r.z0 && z <= r.z1) return true;
      }
      return false;
    });
    const { exclude, doors } = doorways(grid, st.floorY, existingRooms);

    // FLOORS: a slab at floorY over the room-air columns, skipping any already-solid cell (the foundation)
    for (const key of floorCols) {
      const [x, z] = key.split(",").map(Number);
      if (!occ.has(x, st.floorY, z)) placements.push({ op: "voxel", pos: [x, st.floorY, z], block: materials.floor });
    }

    // WALLS: per y in the storey, the divider columns ∩ that height's interior, minus the doorway gaps
    for (let y = st.floorY + 1; y <= st.ceilY; y++) {
      const cols = interiorColumnsAtY(occ, y);
      for (const key of cols) {
        const [x, z] = key.split(",").map(Number);
        if (!isWallColumn(grid, x, z)) continue;
        if (exclude.has(`${x},${y},${z}`)) continue; // doorway = no wall placed (exclusion)
        placements.push({ op: "voxel", pos: [x, y, z], block: materials.wall });
      }
    }

    planStoreys.push({
      index: st.index, floorY: st.floorY, ceilY: st.ceilY,
      rooms: existingRooms.map((r) => r.id), doors,
    });
  }

  const plan = {
    schema: FLOORPLAN_SCHEMA, storeys: planStoreys, grid, materials,
    frontDoor: spec.frontDoor ?? null, doorPolicy: spec.doorPolicy ?? "spanning",
  };
  return { plan, placements };
}

/** Append the floorplan placements to the shell artifact (additive — the interior is air). Thin wrapper
 *  over `applyDeltas`; the one place placements meet the artifact contract. Does NOT validate. PURE. */
export function applyFloorplan(artifact, placements) {
  return applyDeltas(artifact, placements);
}

// ----------------------------------------------------------------------------------------------------
// The plausibility gate (pure) — design-without-reference: validate STRUCTURE, name the residual.
// ----------------------------------------------------------------------------------------------------

/** Union-find connectivity over a storey's rooms via its doors. Rooms with no incident door are isolated.
 *  Returns true iff every listed room is in one component. PURE. */
function roomGraphConnected(roomIds, doors) {
  if (roomIds.length <= 1) return true;
  const parent = new Map(roomIds.map((id) => [id, id]));
  const find = (a) => { while (parent.get(a) !== a) { parent.set(a, parent.get(parent.get(a))); a = parent.get(a); } return a; };
  const union = (a, b) => { const ra = find(a), rb = find(b); if (ra !== rb) parent.set(ra, rb); };
  for (const d of doors) if (parent.has(d.rooms[0]) && parent.has(d.rooms[1])) union(d.rooms[0], d.rooms[1]);
  const root = find(roomIds[0]);
  return roomIds.every((id) => find(id) === root);
}

/** Exterior openings per side face (doors/windows the shell already has). PURE. */
function openingsByFace(occ) {
  const out = [];
  for (const dir of SIDE_FACES) for (const o of openings(occ, dir)) out.push({ dir, ...o });
  return out;
}

/**
 * Openings-align-shell (AC): each exterior opening should have an interior doorway "behind" it. When the
 * geometric read finds NO exterior openings (the cottage — the front-most march hits the outer skin, so a
 * recessed door reads as no hole), this is VACUOUS and becomes the gate's NAMED RESIDUAL (Rule 7 — shown,
 * not hidden), not a hard fail. Pure; the openings list is injectable so it is testable without a holed
 * shell.
 * @param {{dir:string,kind:string}[]} openingsList
 * @param {object} plan
 * @returns {{pass:boolean, detail:string, residual:string|null}}
 */
export function openingsAlignShell(openingsList, plan) {
  const anyDoor = plan.storeys.some((s) => s.doors.length > 0);
  if (openingsList.length === 0) {
    return {
      pass: true,
      detail: "no exterior openings read geometrically; interior doorways present; front-door alignment is steered, not geometric",
      residual: "openings-align: exterior openings unreadable by the front-most ortho march (recessed doors), so interior-door↔exterior-door alignment is STEERED (the LLM's frontDoor), not geometrically verified",
    };
  }
  // with exterior openings: require interior doorways exist (a real circulation behind the shell)
  return {
    pass: anyDoor,
    detail: `${openingsList.length} exterior opening(s); interior doorways ${anyDoor ? "present" : "ABSENT"}`,
    residual: anyDoor ? null : "openings-align: exterior openings exist but no interior doorway connects to them",
  };
}

/**
 * The plausibility gate (AC): per-constraint pass/fail + a named residual (Rule 7). Hard constraints 1–6
 * (rooms valid / non-overlapping / reachable / floors@lines / storey-count / grid-fits) decide `pass`;
 * openings-align is reported and contributes the residual when vacuous. PURE.
 * @param {import("./occupancy.mjs").Occupancy} occ
 * @param {object} read a structuralRead result
 * @param {object} plan a {@link generateFloorplan} plan
 * @returns {{pass:boolean, constraints:{name:string,pass:boolean,detail:string}[], residual:string|null}}
 */
export function gateFloorplan(occ, read, plan) {
  const constraints = [];
  const add = (name, pass, detail) => constraints.push({ name, pass, detail });
  const rooms = plan.grid.rooms;

  // 1. rooms valid — positive area
  const degenerate = rooms.filter((r) => r.x1 < r.x0 || r.z1 < r.z0);
  add("roomsValid", rooms.length > 0 && degenerate.length === 0,
    `${rooms.length} rooms, ${degenerate.length} degenerate`);

  // 2. rooms non-overlapping — pairwise disjoint column boxes
  let overlap = false;
  for (let i = 0; i < rooms.length && !overlap; i++) {
    for (let j = i + 1; j < rooms.length; j++) {
      const a = rooms[i], b = rooms[j];
      if (a.x0 <= b.x1 && b.x0 <= a.x1 && a.z0 <= b.z1 && b.z0 <= a.z1) { overlap = true; break; }
    }
  }
  add("roomsNonOverlap", !overlap, overlap ? "found overlapping rooms" : "all rooms disjoint");

  // 3. reachable — each storey's existing rooms connected by doors
  const unreachable = plan.storeys.filter((s) => !roomGraphConnected(s.rooms, s.doors));
  add("reachable", unreachable.length === 0,
    unreachable.length === 0 ? "every storey's rooms connect by doorways"
      : `${unreachable.length} storey(s) with disconnected rooms`);

  // 4. floors at storey lines
  const lines = new Set(read?.storeyBands?.floorLines ?? []);
  const offLine = plan.storeys.filter((s) => !lines.has(s.floorY));
  add("floorsAtStoreyLines", offLine.length === 0,
    offLine.length === 0 ? "every floor sits on a structural storey line" : `${offLine.length} floor(s) off-line`);

  // 5. storey count matches the structural read
  const expected = (read?.storeyBands?.floorLines ?? []).length;
  add("storeyCountMatches", plan.storeys.length === expected,
    `plan ${plan.storeys.length} vs read ${expected}`);

  // 6. grid fits the envelope — interior inside the footprint bbox, walls strictly inside
  const fp = read?.footprint?.bbox;
  const it = plan.grid.interior;
  const fits = !!fp && !!it && it.x0 >= fp.minX && it.x1 <= fp.maxX && it.z0 >= fp.minZ && it.z1 <= fp.maxZ &&
    plan.grid.xWalls.every((x) => x > fp.minX && x < fp.maxX) &&
    plan.grid.zWalls.every((z) => z > fp.minZ && z < fp.maxZ);
  add("gridFitsEnvelope", fits, fits ? "interior + walls inside the footprint" : "grid exceeds the envelope");

  // 7. openings align (→ residual when vacuous)
  const align = openingsAlignShell(openingsByFace(occ), plan);
  add("openingsAlignShell", align.pass, align.detail);

  const hard = ["roomsValid", "roomsNonOverlap", "reachable", "floorsAtStoreyLines", "storeyCountMatches", "gridFitsEnvelope"];
  const pass = constraints.filter((c) => hard.includes(c.name)).every((c) => c.pass);
  const failResidual = constraints.find((c) => hard.includes(c.name) && !c.pass);
  const residual = failResidual ? `${failResidual.name}: ${failResidual.detail}` : align.residual;
  return { pass, constraints, residual };
}

// ----------------------------------------------------------------------------------------------------
// The metered seam (pure prompt + parser) — the floorplan REASONING is the only metered call.
// ----------------------------------------------------------------------------------------------------

/**
 * The FIXED floorplan-author prompt (STRONG tier). States the footprint, the storey lines, the detected
 * exterior openings (or, when none read, asks the model to identify the front door from the elevation),
 * and the palette manifest, then asks for ONE FloorplanSpec JSON. PURE; the caller delivers the plan +
 * elevation renders alongside.
 * @param {object} read a structuralRead result
 * @param {{index,floorY,ceilY}[]} storeys
 * @param {{width:number,depth:number,area:number}} footprintSummary
 * @param {string[]} manifest the artifact palette ids (the only blocks the model may pick)
 * @returns {string}
 */
export function buildFloorplanPrompt(read, storeys, footprintSummary, manifest = []) {
  const opens = openingsByFace0(read);
  const storeyList = storeys.length
    ? storeys.map((s) => `  - storey ${s.index}: floor y=${s.floorY}, ceiling y=${s.ceilY}`).join("\n")
    : "  (no storey lines read)";
  const openLine = opens.length
    ? opens.map((o) => `  - ${o.kind} on face ${o.dir} at u≈${o.bbox?.u0}`).join("\n")
    : "  (none readable — IDENTIFY the front door from the elevation render and return it as `frontDoor`)";
  return [
    "You are a FLOORPLAN AUTHOR for a Minecraft building. The exterior shell is fixed and HOLLOW; you are",
    "designing the INTERIOR — there is no reference for it, so partition it into a sensible N×M grid of",
    "rooms across the storeys. You see the plan (top) view and an elevation. Steer the generator; the",
    "program does the placement.",
    "",
    `Footprint: ${footprintSummary.width}×${footprintSummary.depth} columns (${footprintSummary.area} occupied).`,
    "Storeys (floors sit on these structural lines — do not invent new heights):",
    storeyList,
    "Exterior openings (the front door interior doorways should sit behind):",
    openLine,
    `Palette — use ONLY these block ids for floor/wall: ${manifest.join(", ") || "(none)"}.`,
    "",
    "## Output — STRICT",
    "Output a SINGLE JSON object and NOTHING else:",
    '{ "rows": <int≥1>, "cols": <int≥1>,',
    '  "materials": { "floor": "<manifest id>", "wall": "<manifest id>" },',
    '  "doorPolicy": "spanning",',
    '  "frontDoor": { "face": "+x|-x|+z|-z", "u": <int> } }',
    "`rows`×`cols` is the room grid. `frontDoor` (optional) is the exterior door the interior aligns behind.",
  ].join("\n");
}

/** Exterior openings for the prompt, tolerant of a read without an occupancy (uses read.wallFields holes
 *  is overkill; the runner passes a real read so openings come from the occupancy via the gate). Here we
 *  only surface what the structural read already carries; empty is the cottage's honest case. PURE. */
function openingsByFace0(read) {
  // The prompt is built from the read summary; the precise opening list comes from the occupancy in the
  // gate. We expose any opening hints the read carries (none on the cottage) — empty is valid + expected.
  return Array.isArray(read?.openings) ? read.openings : [];
}

/**
 * Parse a floorplan-author reply into a validated FloorplanSpec. Coerces rows/cols to int≥1 (default 2),
 * clamps materials to the manifest (else {@link DEFAULT_MATERIALS}), defaults doorPolicy, keeps a
 * well-formed frontDoor. Throws ONLY on non-JSON (reuses `parseJsonReply`). PURE.
 * @param {string} text
 * @param {{manifest?:string[]}} [opts]
 * @returns {{schema:string, rows:number, cols:number, materials:{floor:string,wall:string},
 *   doorPolicy:string, frontDoor:{face:string,u:number}|null}}
 */
export function parseFloorplanSpec(text, { manifest = [] } = {}) {
  let obj;
  try {
    obj = parseJsonReply(text);
  } catch (e) {
    throw new Error(`parseFloorplanSpec: ${e.message}`);
  }
  const intGE1 = (v, d) => (Number.isInteger(v) && v >= 1 ? v : d);
  const allow = new Set(manifest);
  const pick = (v, d) => (typeof v === "string" && (allow.size === 0 || allow.has(v)) ? v : d);
  const m = obj?.materials || {};
  let frontDoor = null;
  if (obj?.frontDoor && SIDE_FACES.includes(obj.frontDoor.face) && Number.isInteger(obj.frontDoor.u)) {
    frontDoor = { face: obj.frontDoor.face, u: obj.frontDoor.u };
  }
  return {
    schema: FLOORPLAN_SCHEMA,
    rows: intGE1(obj?.rows, 2),
    cols: intGE1(obj?.cols, 2),
    materials: { floor: pick(m.floor, DEFAULT_MATERIALS.floor), wall: pick(m.wall, DEFAULT_MATERIALS.wall) },
    doorPolicy: typeof obj?.doorPolicy === "string" ? obj.doorPolicy : "spanning",
    frontDoor,
  };
}
